using System;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Web.Script.Serialization;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media.Imaging;

static class FocusChecks {
 static void Check(bool condition,string message){if(!condition)throw new Exception(message);}
 static void Reject(Action action,string message){bool rejected=false;try{action();}catch{rejected=true;}Check(rejected,message);}
 public static void Run(Window owner){
  var now=new DateTime(2026,10,30,16,0,0,DateTimeKind.Utc);var settings=new FocusSettings{defaultMinutes=45,breakMinutes=10,autoStartBreak=true,blockedProcesses=new string[0],disabledWorkspaces=new string[0]};var state=FocusSession.Start(settings,"  Finish three problems  ",now);
  Check(state.phase=="work"&&state.Running&&state.goal=="Finish three problems"&&state.Remaining(now)==2700&&!state.ThemeActive,"Gentle session start/goal/theme failed");
  FocusSession.Pause(state,now.AddMinutes(12));Check(state.paused&&!state.Running&&state.remainingSeconds==1980&&!FocusSession.Advance(state,now.AddDays(1)),"Paused time must not elapse");FocusSession.Resume(state,now.AddDays(1));Check(state.Running&&state.Remaining(now.AddDays(1))==1980,"Resume must preserve remaining time");FocusSession.Extend(state,now.AddDays(1));Check(state.Remaining(now.AddDays(1))==2280&&state.totalSeconds==3000,"+5 minutes must extend time and progress duration");
  Check(FocusSession.Advance(state,now.AddDays(1).AddMinutes(38))&&state.phase=="break"&&state.Running&&state.completedSessions==1&&state.Remaining(now.AddDays(1).AddMinutes(38))==600,"Work must transition into the custom break");FocusSession.Advance(state,now.AddDays(1).AddMinutes(48));Check(state.phase=="work"&&state.waiting&&!state.Running&&state.remainingSeconds==2700,"Next work session must wait for an explicit start");
  settings.autoStartBreak=false;state=FocusSession.Start(settings,"",now);FocusSession.Advance(state,now.AddHours(20));Check(state.phase=="break"&&state.waiting&&state.completedSessions==1,"Sleep/late recovery must not invent multiple completed cycles");FocusSession.Resume(state,now.AddHours(20));FocusSession.Pause(state,now.AddHours(20).AddMinutes(2));var json=new JavaScriptSerializer();var restored=json.Deserialize<FocusState>(json.Serialize(state));Check(restored.paused&&restored.phase=="break"&&restored.remainingSeconds==480,"Paused break must survive restart serialization");
  settings.autoStartBreak=true;state=FocusSession.Start(settings,"Finish three problems",DateTime.UtcNow.AddMinutes(-20));Check(state.Active&&!state.ThemeActive,"Working session must not activate the old green theme");var baseline=new ControlCenterPalette(new FocusState());var gentle=new ControlCenterPalette(state);Check(baseline.Colors["Accent"]==gentle.Colors["Accent"]&&baseline.Colors["Surface"]==gentle.Colors["Surface"],"Gentle focus must preserve the existing palette");
  Reject(()=>FocusMode.Validate(new FocusSettings{hiddenProcesses=new[]{"explorer.exe"}}),"Critical system processes must not be hidden");Reject(()=>FocusMode.Validate(new FocusSettings{breakMinutes=0}),"Break length must be validated");
  Check(IndicatorKeys.Code("leftalt")==0xA4&&IndicatorKeys.Code("rightctrl")==0xA3&&IndicatorKeys.Code("none")==0,"Default/disabled indicator keys incorrect");Reject(()=>IndicatorKeys.Validate(new IndicatorKeySettings{workspace="rightctrl",wallpaper="rightctrl"}),"Duplicate indicator keys must be rejected");IndicatorKeys.Validate(new IndicatorKeySettings{workspace="none",wallpaper="none"});
  Check(IndicatorKeys.Choices.Single(k=>k.Name=="rightctrl").ToString()=="Right Ctrl","Key picker items must display human-readable names");
  CheckWindowRestoration();
  string path=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"indicator-keys.json");string previous=File.Exists(path)?File.ReadAllText(path):null;try{IndicatorKeys.Save(new IndicatorKeySettings{workspace="rightshift",wallpaper="rightctrl"});Check(IndicatorKeys.Load().workspace=="rightshift","Indicator binds must persist and reload");Reject(()=>IndicatorKeys.Save(new IndicatorKeySettings{workspace="bad",wallpaper="rightctrl"}),"Invalid bind must not overwrite saved keys");Check(IndicatorKeys.Load().workspace=="rightshift","Failed bind save changed existing configuration");}finally{if(previous==null)File.Delete(path);else File.WriteAllText(path,previous);}
  var focusPage=(StackPanel)typeof(NordControlCenter).GetField("focusPage",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(owner);Check(focusPage.Children.Count==0,"Focus controls should be lazy until the tab is opened/measured");var fit=typeof(NordControlCenter).GetMethod("Fit",BindingFlags.NonPublic|BindingFlags.Instance);fit.Invoke(owner,new object[]{NordControlCenter.FocusTab});var built=focusPage.Children[0];fit.Invoke(owner,new object[]{NordControlCenter.FocusTab});Check(focusPage.Children.Count==1&&ReferenceEquals(built,focusPage.Children[0]),"Focus tab must reuse its controls");var timer=(System.Windows.Threading.DispatcherTimer)typeof(FocusView).GetField("timer",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(built);Check(!timer.IsEnabled,"Hidden focus tab must not run a UI timer");
  var view=new FocusView(()=>state);var frame=new Border{Width=488,Padding=new Thickness(0),Resources=owner.Resources,Background=ControlCenterTheme.Current.Brush("Surface"),Child=view};System.Windows.Documents.TextElement.SetFontFamily(frame,owner.FontFamily);System.Windows.Documents.TextElement.SetForeground(frame,ControlCenterTheme.Current.Brush("Text"));frame.Measure(new Size(488,double.PositiveInfinity));frame.Arrange(new Rect(frame.DesiredSize));frame.UpdateLayout();var image=new RenderTargetBitmap(976,(int)Math.Ceiling(frame.ActualHeight*2),192,192,System.Windows.Media.PixelFormats.Pbgra32);image.Render(frame);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(image));using(var file=File.Create(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"focus-session.png")))png.Save(file);
  Console.WriteLine("PASS: custom work/break cycle, optional goals, pause/resume, +5 min, deliberate next work session, late/restart recovery, unchanged palette, validated persistent indicator binds and lazy Focus UI with no hidden-tab timer. No windows hidden or processes closed.");
 }
 static void CheckWindowRestoration(){
  var find=FocusMode.FindWindows;var hide=FocusMode.HideWindow;var restore=FocusMode.RestoreWindow;bool visible=true;int hides=0,restores=0;
  string root=AppDomain.CurrentDomain.BaseDirectory;var paths=new[]{Path.Combine(root,"focus-mode.json"),Path.Combine(root,"focus-state.json")};var saved=paths.Select(p=>File.Exists(p)?File.ReadAllText(p):null).ToArray();
  var window=new HiddenFocusWindow{handle=123,pid=456,processKey="456:test-start-time"};
  try{
   FocusMode.FindWindows=names=>visible?new[]{window}:new HiddenFocusWindow[0];FocusMode.HideWindow=w=>{var journal=new JavaScriptSerializer().Deserialize<FocusState>(File.ReadAllText(paths[1]));Check(journal.hiddenWindows.Any(x=>x.handle==w.handle&&x.processKey==w.processKey),"Window identity must be persisted before hiding");visible=false;hides++;};FocusMode.RestoreWindow=w=>{Check(w.processKey==window.processKey,"Restore must retain the process identity guard");visible=true;restores++;return true;};
   FocusMode.Start(new FocusSettings{hiddenProcesses=new[]{"focus-check-app.exe"},blockedProcesses=new string[0],disabledWorkspaces=new string[0]},"Check window recovery").GetAwaiter().GetResult();Check(!visible&&hides==1&&FocusMode.Error=="","Start must hide only after journaling: "+FocusMode.Error);
   window=new HiddenFocusWindow{handle=123,pid=789,processKey="789:new-process-identity"};visible=true;FocusMode.Command("extend").GetAwaiter().GetResult();Check(!visible&&hides==2,"A reused window handle must receive a new recovery identity before hiding");
   FocusMode.Command("pause").GetAwaiter().GetResult();Check(visible&&FocusMode.State.paused,"Pause must restore hidden windows");FocusMode.Command("resume").GetAwaiter().GetResult();Check(!visible&&hides==3,"Resume must hide selected windows again");FocusMode.Command("break").GetAwaiter().GetResult();Check(visible&&FocusMode.State.phase=="break","A break must restore hidden windows");FocusMode.Command("work").GetAwaiter().GetResult();Check(!visible,"Starting work after a break must hide distractions");FocusMode.Command("end").GetAwaiter().GetResult();Check(visible&&!FocusMode.State.HasSession&&restores==3,"End must restore windows and clear the session");
  }finally{FocusMode.Command("end").GetAwaiter().GetResult();FocusMode.FindWindows=find;FocusMode.HideWindow=hide;FocusMode.RestoreWindow=restore;for(int i=0;i<paths.Length;i++){if(saved[i]==null)File.Delete(paths[i]);else File.WriteAllText(paths[i],saved[i]);}}
  Console.WriteLine("PASS: mock-window integration journals before hiding and restores on pause, break and end; resume/work re-hide; no real desktop windows affected.");
 }
}
